def most_common(items):
    counts = {}
    for item in items:
        counts[item] = counts.get(item, 0) + 1

    best = None
    best_count = 0
    for item, count in counts.items():
        if count > best_count:
            best = item
            best_count = count
    return best

print(most_common(["b", "a", "b", "c", "b"]))

